Az alábbi „kurva legfejlettebb” koncepció egyetlen főfájlban (`main.py`) valósítja meg a teljes, többügynökös, dinamikus kutatási folyamatot, funkcióhívásokkal és strukturált kimenettel, míg az `index.html` a minimális, de élő frissítést támogató UI-t adja.

## main.py  
```python
import os, json, time
from flask import Flask, request, Response, send_from_directory
from exapy import Exa
from cerebras.cloud.sdk import Cerebras, APIError, RateLimitError

# Inicializálás (= .env + Replit Secrets)
exa = Exa(os.getenv("EXAAPIKEY"))
cerebras = Cerebras(os.getenv("CEREBRASAPIKEY"))

# 1) Definiáljuk a beépített „eszközöket” a LLM-hez (tool calling)
FUNCTIONS = [
  {
    "name": "search_exa",
    "description": "Kombinált kulcsszavas és neurális webes keresés Exa API-val",
    "parameters": {
      "type": "object",
      "properties": {
        "query": {"type": "string", "description": "Kutatási kifejezés"},
        "n": {"type": "integer", "description": "Találatok száma"}
      },
      "required": ["query"]
    }
  },
  {
    "name": "analyze_cerebras",
    "description": "Források elemzése és összefoglalása Cerebras LLM-mel",
    "parameters": {
      "type": "object",
      "properties": {
        "texts": {
          "type": "array",
          "items": {"type": "string"},
          "description": "Elemzendő szövegdarabok listája"
        }
      },
      "required": ["texts"]
    }
  }
]

def call_search(query, n):
    res = exa.search(query=query, numresults=n, type="auto")
    ids = [r.id for r in res.results]
    cont = exa.searchandcontents(ids=ids, text=True, highlights=True)
    return [c.text for c in cont.results]

def call_analyze(texts):
    resp = cerebras.chat.completions.create(
        model="gpt-oss-120b",
        messages=[{"role":"system","content":"Mélyelemző ügynök vagy."},
                  {"role":"user","content":json.dumps(texts)}],
        temperature=0.2,
        functions=[],
        stream=False
    )
    return resp.choices[0].message.content

@app.route('/')
def index():
    return send_from_directory('.', 'index.html')

@app.route('/api/research', methods=['POST'])
def research():
    topic = request.json.get("query", "")
    def stream():
        # 2) Indító prompt, primer agent-hívás
        messages = [
            {"role":"system","content":"Te egy autonóm deepsearch ügynök vagy."},
            {"role":"user","content":f"Kutatási téma: {topic}"}
        ]
        # 3) Multi-turn tool use ciklus
        for i in range(4):
            try:
                resp = cerebras.chat.completions.create(
                    model="gpt-oss-120b",
                    messages=messages,
                    functions=FUNCTIONS,
                    function_call="auto",
                    temperature=0.1
                )
            except RateLimitError:
                time.sleep(2); continue
            msg = resp.choices[0].message
            if msg.function_call:
                name = msg.function_call.name
                args = json.loads(msg.function_call.arguments or "{}")
                if name == "search_exa":
                    texts = call_search(args["query"], args.get("n", 5))
                    messages.append({"role":"tool","name":name,"content":json.dumps(texts)})
                    yield f"data: Keresés ({args['query']}) → {len(texts)} forrás\n\n"
                elif name == "analyze_cerebras":
                    summary = call_analyze(json.loads(messages[-1]["content"]))
                    messages.append({"role":"tool","name":name,"content":summary})
                    yield f"data: Elemzés kész: {summary[:80]}...\n\n"
            else:
                # végső szintézis
                final = msg.content
                yield f"data: Végső jelentés:\n\n{final}\n\n"
                break
        yield "data: END\n\n"
    return Response(stream(), mimetype='text/event-stream')

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=3000)
```
– A `FUNCTIONS` tömb tartalmazza az Exa- és Cerebras-eszközök JSON-sémáját, ezáltal a LLM maga hívja meg azokat [1][2].  
– A Flask SSE streamben küldi a frontendnek az ügynök státuszát és a végső riportot, így a felhasználó valós időben látja az előrehaladást [3].

## index.html  
```html
<!DOCTYPE html>
<html lang="hu">
<head>
  <meta charset="UTF-8">
  <title>HyperDeepSearch Agent</title>
  <style>
    body{font-family:sans-serif;max-width:600px;margin:2em auto;}
    #report{white-space:pre-wrap;background:#f5f5f5;padding:1em;border-radius:5px;}
  </style>
</head>
<body>
  <h1>HyperDeepSearch AI Agent</h1>
  <input id="query" placeholder="Kutatási téma..." style="width:100%;padding:0.5em;">
  <button id="start">Kutatás indítása</button>
  <div id="report"></div>
  <script>
    document.getElementById('start').onclick = () => {
      const q=document.getElementById('query').value;
      if(!q) return alert('Adj meg témát!');
      document.getElementById('report').textContent='→ Indul a kutatás...\n';
      const evt = new EventSource(`/api/research`, {withCredentials:true});
      evt.onmessage = e => {
        if(e.data==='END'){evt.close(); return;}
        document.getElementById('report').textContent += e.data + '\n';
      };
    };
  </script>
</body>
</html>
```
– Az `EventSource` segítségével azonnal megérkeznek a backend üzenetek: forráslekérdezések, elemzések és végső szintézis [3].  
– Csupán a csatolt Exa- és Cerebras-SDK-kra, valamint a meglévő környezeti változókra épít, más API-t nem használ [1][2].

Az alábbi `main.py` és `index.html` fájl kizárólag az Ön által csatolt Exa- és Cerebras-dokumentációkra, valamint a rendelkezésre álló környezeti változókra épít [1][2].

