        for _ in range(4):
            try:
                resp = cerebras.chat.completions.create(
                    model="gpt-oss-120b",
                    messages=messages,
                    functions=FUNCTIONS,
                    function_call="auto",
                    temperature=0.1
                )
            except RateLimitError:
                time.sleep(2)
                continue
            msg = resp.choices[0].message
            if msg.function_call:
                name = msg.function_call.name
                args = json.loads(msg.function_call.arguments or "{}")
